class Attempts:
    def __init__(self, count):
        if count < 0:
            raise ValueError("negative attempts")
        self.remaining = count
    def __iter__(self):
        return self
    def __next__(self):
        if self.remaining == 0:
            raise StopIteration
        self.remaining -= 1
        return self.remaining
