import csv
from pathlib import Path
from tempfile import TemporaryDirectory
def read_totals(path):
    with path.open(encoding="utf-8", newline="") as stream:
        rows = csv.DictReader(stream)
        if rows.fieldnames != ["name", "quantity"]:
            raise ValueError("unexpected headers")
        result = {}
        for row in rows:
            if None in row or any(value is None for value in row.values()):
                raise ValueError("wrong row width")
            quantity = int(row["quantity"])
            if quantity < 0:
                raise ValueError("negative quantity")
            result[row["name"]] = result.get(row["name"], 0) + quantity
        return result
with TemporaryDirectory() as folder:
    path = Path(folder) / "orders.csv"
    path.write_text('name,quantity\n"café, beans",2\n', encoding="utf-8")
    assert read_totals(path) == {"café, beans": 2}
    path.write_text("name,quantity\n", encoding="utf-8")
    assert read_totals(path) == {}
    for text in ["bad,headers\n", "name,quantity\nAda\n", "name,quantity\nAda,2,extra\n", "name,quantity\nAda,bad\n"]:
        path.write_text(text, encoding="utf-8")
        try:
            read_totals(path)
        except ValueError:
            pass
        else:
            raise AssertionError("bad CSV accepted")

